// MycorrhizaRenderer, network style "Mycelium": the GPU half of the port of
// tools/mycelium_lookdev/index.html (see MycorrhizaRenderer.h and
// MyceliumSim.h). Passes, in the page's order: swirl directions and line
// integral convolution (only when MyceliumSim asks for a rebuild), fibre
// advection (ping-pong), threads into a mask, shading, bloom (bright pass,
// two blur levels), tone map, then the image is mapped onto the sand.
// Shaders: bin/data/shaders/mycorrhiza/GL2|GL3/myc_*, generated by
// tools/mycorrhiza_harness/gen_mycelium_shaders.py.
#include "MycorrhizaRenderer.h"
#include "../../KinectProjector/KinectProjector.h"
#include "../../Games/VegetationField.h"
#include "ofxImGui.h"
#include <map>

typedef MycorrhizaField MF;
typedef MyceliumSim MS;

// Page defaults (DEFAULTS in the page). Sand visibility: the page's 0.12 simulates room light on
// sand in the browser; on the projector it would light the untouched sand, so 0 here (DEVLOG).
float MycorrhizaRenderer::M_FIBRE_LEN = 50.0f;
float MycorrhizaRenderer::M_FIBRE = 1.2f;
float MycorrhizaRenderer::M_SWIRL_SCALE = 6.0f;
float MycorrhizaRenderer::M_STROKE_W = 0.9f;
float MycorrhizaRenderer::M_STREAK_FLOW = 25.0f;
float MycorrhizaRenderer::M_TEX_SLOPE = 0.0f;
float MycorrhizaRenderer::M_CARRY = 0.6f;
float MycorrhizaRenderer::M_RELAX = 0.3f;
float MycorrhizaRenderer::M_MATURE = 4.0f;
float MycorrhizaRenderer::M_EDGE_COOL = 0.6f;
float MycorrhizaRenderer::M_EXPOSURE = 1.4f;
float MycorrhizaRenderer::M_CONTRAST = 3.2f;
float MycorrhizaRenderer::M_GAMMA = 1.3f;
float MycorrhizaRenderer::M_BASE = 0.14f;
float MycorrhizaRenderer::M_LIGHT_COL = 0.0f;
float MycorrhizaRenderer::M_SHEEN = 0.4f;
float MycorrhizaRenderer::M_RELIEF = 0.6f;
float MycorrhizaRenderer::M_FIB_RELIEF = 2.0f;
float MycorrhizaRenderer::M_SHINE = 30.0f;
float MycorrhizaRenderer::M_RIM = 0.3f;
float MycorrhizaRenderer::M_BLOOM = 0.5f;
float MycorrhizaRenderer::M_BLOOM_THRESH = 0.6f;
float MycorrhizaRenderer::M_SAND = 0.0f;
float MycorrhizaRenderer::M_THREAD_BRIGHT = 0.45f;
float MycorrhizaRenderer::M_PULSE_GAIN = 0.8f;
float MycorrhizaRenderer::M_PULSE_SPEED = 0.6f;
float MycorrhizaRenderer::M_PULSE_LEN = 45.0f;
float MycorrhizaRenderer::M_PULSE_SHARP = 3.0f;
float MycorrhizaRenderer::M_MIN_THREAD_PX = 1.5f;
float MycorrhizaRenderer::M_BRUSH = 34.0f;
float MycorrhizaRenderer::M_CARVE = 10.0f;
float MycorrhizaRenderer::M_PILE = 0.6f;
static ofFloatColor hexColor(unsigned v) { return ofFloatColor(((v >> 16) & 255) / 255.0f, ((v >> 8) & 255) / 255.0f, (v & 255) / 255.0f); }
ofFloatColor MycorrhizaRenderer::M_C0 = hexColor(0x3FD8FF);
ofFloatColor MycorrhizaRenderer::M_C1 = hexColor(0xCFEFFF);
ofFloatColor MycorrhizaRenderer::M_C2 = hexColor(0xFFB347);
ofFloatColor MycorrhizaRenderer::M_C3 = hexColor(0xF07A2A);
ofFloatColor MycorrhizaRenderer::M_TROUGH = hexColor(0x0A2A6E);
ofFloatColor MycorrhizaRenderer::M_THREAD_COL = hexColor(0xCFF4FF);

void MycorrhizaRenderer::applyPalette(int which)
{
	static const unsigned P[3][5] = {
		{ 0x3FD8FF, 0xCFEFFF, 0xFFB347, 0xF07A2A, 0x0A2A6E },   // Cyan and amber
		{ 0x0E2A7A, 0x4F8FD6, 0xFFB347, 0xFF7A1A, 0x050A1E },   // Blue and gold
		{ 0x3FD8FF, 0x7A3FD1, 0xE040C8, 0xFFA640, 0x1A0F3A } }; // Violet
	which = std::min(2, std::max(0, which));
	M_C0 = hexColor(P[which][0]); M_C1 = hexColor(P[which][1]); M_C2 = hexColor(P[which][2]); M_C3 = hexColor(P[which][3]);
	M_TROUGH = hexColor(P[which][4]);
}

static ofFbo::Settings fboSettings(int w, int h)
{
	ofFbo::Settings s;
	s.width = std::max(1, w);
	s.height = std::max(1, h);
	s.internalformat = GL_RGBA16F;
	s.textureTarget = GL_TEXTURE_RECTANGLE_ARB;
	s.wrapModeHorizontal = GL_CLAMP_TO_EDGE;
	s.wrapModeVertical = GL_CLAMP_TO_EDGE;
	s.minFilter = GL_LINEAR;
	s.maxFilter = GL_LINEAR;
	s.useDepth = false;
	s.useStencil = false;
	return s;
}

// The page's 256 x 256 noise of random bytes; a fixed generator (the harness uses the same one).
static void noiseBytes(std::vector<unsigned char> & n)
{
	n.resize(256 * 256 * 4);
	uint32_t s = 12345u;
	for (int i = 0; i < 256 * 256; i++) {
		s = s * 1664525u + 1013904223u;
		const unsigned char v = (unsigned char)(s >> 24);
		n[4 * i] = n[4 * i + 1] = n[4 * i + 2] = v;
		n[4 * i + 3] = 255;
	}
}

void MycorrhizaRenderer::myceliumAllocate()
{
	const MS & sim = field.getMycelium();
	const int fw = sim.getCols() * std::max(1, MS::FIB_PX), fh = sim.getRows() * std::max(1, MS::FIB_PX);
	if (fw == mFW && fh == mFH && mBase.isAllocated())
		return;
	mFW = fw; mFH = fh;
	mSwirl.allocate(fboSettings(fw / 4, fh / 4));
	for (ofFbo * f : { &mBase, &mFibA, &mFibB, &mThreads, &mShadeFbo, &mFinalFbo }) f->allocate(fboSettings(fw, fh));
	mB1a.allocate(fboSettings(fw / 2, fh / 2)); mB1b.allocate(fboSettings(fw / 2, fh / 2));
	mB2a.allocate(fboSettings(fw / 8, fh / 8)); mB2b.allocate(fboSettings(fw / 8, fh / 8));
	if (!mNoiseTex.isAllocated()) {
		std::vector<unsigned char> n;
		noiseBytes(n);
		mNoiseTex.allocate(256, 256, GL_RGBA8, false); // normalised coordinates, repeat
		mNoiseTex.loadData(n.data(), 256, 256, GL_RGBA);
		mNoiseTex.setTextureMinMagFilter(GL_LINEAR, GL_LINEAR);
		mNoiseTex.setTextureWrap(GL_REPEAT, GL_REPEAT);
	}
	mFibValid = false;
}

void MycorrhizaRenderer::quadPass(ofFbo & dst, ofShader & sh, const std::function<void(ofShader &)> & setup)
{
	static std::map<std::pair<int, int>, ofMesh> quads;
	const int w = (int)dst.getWidth(), h = (int)dst.getHeight();
	ofMesh & q = quads[std::make_pair(w, h)];
	if (q.getNumVertices() == 0) {
		q.setMode(OF_PRIMITIVE_TRIANGLE_FAN);
		const glm::vec3 v[4] = { glm::vec3(0, 0, 0), glm::vec3(w, 0, 0), glm::vec3(w, h, 0), glm::vec3(0, h, 0) };
		for (int i = 0; i < 4; i++) { q.addVertex(v[i]); q.addTexCoord(glm::vec2(v[i].x, v[i].y)); }
	}
	dst.begin();
	ofPushStyle();
	ofEnableBlendMode(OF_BLENDMODE_DISABLED);
	ofSetColor(255);
	sh.begin();
	sh.setUniform2f("uRes", (float)w, (float)h);
	setup(sh);
	q.draw();
	sh.end();
	ofPopStyle();
	dst.end();
}

// Projector pixels per grid-space image pixel, from the calibration mesh (centre).
float MycorrhizaRenderer::projPxPerFibPx() const
{
	if (meshCols < 3 || meshRows < 3) return 1.0f;
	const int i = meshCols / 2, j = meshRows / 2;
	const glm::vec3 & a = mesh.getVertices()[(size_t)j * meshCols + i];
	const glm::vec3 & b = mesh.getVertices()[(size_t)j * meshCols + i + 1];
	const glm::vec3 & c = mesh.getVertices()[(size_t)(j + 1) * meshCols + i];
	const float d = 0.5f * (glm::length(b - a) + glm::length(c - a)); // projector px per 4 grid cells (LUT step)
	return std::max(0.05f, d / (4.0f * std::max(1, MS::FIB_PX)));
}

// Per cell RGBA32F: lit, age, stroke direction; aux: model warming, smoothed sand; liquid: depth, velocity.
void MycorrhizaRenderer::myceliumUpload()
{
	const uint64_t t0 = ofGetElapsedTimeMicros();
	const MS & sim = field.getMycelium();
	const int W = sim.getCols(), H = sim.getRows(), LW = sim.getLiquidCols(), LH = sim.getLiquidRows();
	auto prep = [](ofTexture & t, int w, int h) {
		if (!t.isAllocated() || (int)t.getWidth() != w || (int)t.getHeight() != h) {
			t.allocate(w, h, GL_RGBA32F, true);
			t.setTextureMinMagFilter(GL_LINEAR, GL_LINEAR);
			t.setTextureWrap(GL_CLAMP_TO_EDGE, GL_CLAMP_TO_EDGE);
		}
	};
	const size_t n = (size_t)W * H, ln = (size_t)LW * LH;
	mMaskBuf.resize(n * 4); mAuxBuf.resize(n * 4); mLiqBuf.resize(ln * 4);
	for (size_t i = 0; i < n; i++) {
		mMaskBuf[4 * i] = sim.lit()[i]; mMaskBuf[4 * i + 1] = sim.age()[i];
		mMaskBuf[4 * i + 2] = sim.dirX()[i]; mMaskBuf[4 * i + 3] = sim.dirY()[i];
		mAuxBuf[4 * i] = sim.modelWarm()[i]; mAuxBuf[4 * i + 1] = sim.smoothSand()[i];
		mAuxBuf[4 * i + 2] = 0.0f; mAuxBuf[4 * i + 3] = 1.0f;
	}
	for (size_t l = 0; l < ln; l++) {
		mLiqBuf[4 * l] = sim.liquidDepth()[l]; mLiqBuf[4 * l + 1] = sim.liquidVelX()[l];
		mLiqBuf[4 * l + 2] = sim.liquidVelY()[l]; mLiqBuf[4 * l + 3] = 1.0f;
	}
	prep(mMaskTex, W, H); prep(mAuxTex, W, H); prep(mLiqTex, LW, LH);
	mMaskTex.loadData(mMaskBuf.data(), W, H, GL_RGBA);
	mAuxTex.loadData(mAuxBuf.data(), W, H, GL_RGBA);
	mLiqTex.loadData(mLiqBuf.data(), LW, LH, GL_RGBA);
	mUploadMs = (ofGetElapsedTimeMicros() - t0) / 1000.0f;
}

// Six vertices per segment as the page's uploadSegments: ends extended by w/2,
// sides at +-1.5 w (side attribute +-1.5); width at least M_MIN_THREAD_PX on the projector.
void MycorrhizaRenderer::myceliumWriteSegment(size_t slot, const MS::Segment & sg)
{
	glm::vec3 * P = &mRingPos[slot * 6];
	glm::vec2 * T = &mRingTex[slot * 6];
	glm::vec3 * N = &mRingNorm[slot * 6];
	if (sg.width <= 0.0f) {
		for (int k = 0; k < 6; k++) { P[k] = glm::vec3(0); T[k] = glm::vec2(0); N[k] = glm::vec3(0); }
		return;
	}
	const float w = std::max(sg.width, M_MIN_THREAD_PX / projPxPerFibPx());
	float dx = sg.x1 - sg.x0, dy = sg.y1 - sg.y0;
	const float len = std::sqrt(dx * dx + dy * dy);
	if (len > 1e-5f) { dx /= len; dy /= len; } else { dx = 1; dy = 0; }
	const float ax = sg.x0 - dx * w * 0.5f, ay = sg.y0 - dy * w * 0.5f, bx = sg.x1 + dx * w * 0.5f, by = sg.y1 + dy * w * 0.5f;
	const float nx = -dy * w * 1.5f, ny = dx * w * 1.5f;
	const glm::vec3 pos[6] = { glm::vec3(ax + nx, ay + ny, 0), glm::vec3(ax - nx, ay - ny, 0), glm::vec3(bx + nx, by + ny, 0),
		glm::vec3(bx + nx, by + ny, 0), glm::vec3(ax - nx, ay - ny, 0), glm::vec3(bx - nx, by - ny, 0) };
	const float side[6] = { 1.5f, -1.5f, 1.5f, 1.5f, -1.5f, -1.5f };
	const float s[6] = { sg.s0, sg.s0, sg.s1, sg.s1, sg.s0, sg.s1 };
	for (int k = 0; k < 6; k++) {
		P[k] = pos[k];
		T[k] = glm::vec2(side[k], s[k]);
		N[k] = glm::vec3(sg.phase, sg.birth, sg.hue);
	}
}

void MycorrhizaRenderer::myceliumSyncThreads()
{
	const uint64_t t0 = ofGetElapsedTimeMicros();
	const std::deque<MS::Segment> & segs = field.getMycelium().segments();
	const size_t cap = (size_t)std::max(1, MS::MAX_SEGMENTS);
	auto upload = [&](size_t slot0, size_t count) {
		if (!count) return;
		const size_t v0 = slot0 * 6, nv = count * 6;
		mRing.getVertexBuffer().updateData(v0 * sizeof(glm::vec3), nv * sizeof(glm::vec3), &mRingPos[v0]);
		mRing.getTexCoordBuffer().updateData(v0 * sizeof(glm::vec2), nv * sizeof(glm::vec2), &mRingTex[v0]);
		mRing.getNormalBuffer().updateData(v0 * sizeof(glm::vec3), nv * sizeof(glm::vec3), &mRingNorm[v0]);
	};
	if (cap != mRingCap) {
		mRingCap = cap;
		mRingPos.assign(cap * 6, glm::vec3(0)); mRingTex.assign(cap * 6, glm::vec2(0)); mRingNorm.assign(cap * 6, glm::vec3(0));
		for (const MS::Segment & s : segs) myceliumWriteSegment((size_t)(s.id % cap), s);
		mRing.clear();
		mRing.setVertexData(mRingPos.data(), (int)mRingPos.size(), GL_DYNAMIC_DRAW);
		mRing.setTexCoordData(mRingTex.data(), (int)mRingTex.size(), GL_DYNAMIC_DRAW);
		mRing.setNormalData(mRingNorm.data(), (int)mRingNorm.size(), GL_DYNAMIC_DRAW);
		mRingNext = segs.empty() ? 0 : segs.back().id + 1;
	} else if (!segs.empty() && segs.back().id + 1 > mRingNext) {
		size_t first = segs.size();
		while (first > 0 && segs[first - 1].id >= mRingNext) first--;
		const uint64_t id0 = segs[first].id, id1 = segs.back().id + 1;
		for (size_t k = first; k < segs.size(); k++) myceliumWriteSegment((size_t)(segs[k].id % cap), segs[k]);
		const size_t n = (size_t)std::min<uint64_t>(id1 - id0, cap), s0 = (size_t)(id0 % cap), part = std::min(n, cap - s0);
		upload(s0, part);
		upload(0, n - part);
		mRingNext = id1;
	}
	for (uint64_t id : field.getMycelium().segmentsRemovedThisStep()) {
		const size_t slot = (size_t)(id % cap);
		MS::Segment z{ 0, 0, 0, 0, 0.0f, 0, 0, 0, 0, 0, 0 };
		myceliumWriteSegment(slot, z);
		upload(slot, 1);
	}
	mThreadMs = (ofGetElapsedTimeMicros() - t0) / 1000.0f;
}

void MycorrhizaRenderer::myceliumRender()
{
	if (!myceliumShadersLoaded || !fbo.isAllocated())
		return;
	MS & sim = field.getMycelium();
	myceliumAllocate();
	const ofVec2f maskSize((float)sim.getCols(), (float)sim.getRows()), liqSize((float)sim.getLiquidCols(), (float)sim.getLiquidRows());
	const float dt = std::min(0.1f, std::max(0.001f, (float)ofGetLastFrameTime()));
	const float now = (float)sim.getTime();
	// Base texture: swirl directions, then LIC (page makeBase), when the simulation asks.
	if (sim.baseDirty() || !mFibValid) {
		quadPass(mSwirl, mCurl, [&](ofShader & s) {
			s.setUniformTexture("uMask", mMaskTex, 1); s.setUniformTexture("uAux", mAuxTex, 2);
			s.setUniform2f("uMaskSize", maskSize.x, maskSize.y);
			s.setUniform1f("uScale", M_SWIRL_SCALE); s.setUniform1f("uSlopeW", M_TEX_SLOPE); s.setUniform1f("uStrokeW", M_STROKE_W);
		});
		quadPass(mBase, mLic, [&](ofShader & s) {
			s.setUniformTexture("uVel", mSwirl.getTexture(), 1); s.setUniformTexture("uNoise", mNoiseTex, 2);
			s.setUniform2f("uVelSize", mSwirl.getWidth(), mSwirl.getHeight());
			s.setUniform1f("uLen", M_FIBRE_LEN); s.setUniform1f("uFibre", M_FIBRE);
		});
		sim.baseRebuilt();
	}
	// Fibre field: advected and settling (page fsFib); after a clear it starts as the base (page resetFib).
	ofFbo & src = mFibCurrentA ? mFibA : mFibB;
	ofFbo & dst = mFibCurrentA ? mFibB : mFibA;
	const bool reset = !mFibValid;
	quadPass(dst, mFib, [&](ofShader & s) {
		s.setUniformTexture("uFib", reset ? mBase.getTexture() : src.getTexture(), 1); s.setUniformTexture("uBase", mBase.getTexture(), 2);
		s.setUniformTexture("uLiq", mLiqTex, 3); s.setUniformTexture("uMask", mMaskTex, 4);
		s.setUniform2f("uLiqSize", liqSize.x, liqSize.y); s.setUniform2f("uMaskSize", maskSize.x, maskSize.y);
		s.setUniform1f("uDt", reset ? 0.0f : dt); s.setUniform1f("uRelax", M_RELAX); s.setUniform1f("uCarry", M_CARRY);
		s.setUniform1f("uStreakFlow", M_STREAK_FLOW);
	});
	mFibCurrentA = !mFibCurrentA;
	mFibValid = true;
	ofFbo & fibNow = mFibCurrentA ? mFibA : mFibB;
	// Threads into their mask (page drawThreads), additive.
	mThreads.begin();
	ofClear(0, 0, 0, 255);
	if (MS::THREADS_ON && mRingNext > 0) {
		ofPushStyle();
		ofEnableBlendMode(OF_BLENDMODE_DISABLED);
		glEnable(GL_BLEND);
		glBlendFunc(GL_ONE, GL_ONE);
		mThread.begin();
		mThread.setUniform1f("uTime", now); mThread.setUniform1f("uFade", sim.fadeRate());
		mThread.setUniform1f("uPulseSpeed", M_PULSE_SPEED); mThread.setUniform1f("uPulseLen", std::max(1.0f, M_PULSE_LEN));
		mThread.setUniform1f("uPulseSharp", M_PULSE_SHARP);
		mRing.draw(GL_TRIANGLES, 0, (int)(std::min<uint64_t>(mRingNext, mRingCap) * 6));
		mThread.end();
		ofPopStyle();
		ofEnableBlendMode(OF_BLENDMODE_ALPHA);
	}
	mThreads.end();
	// Shade (page fsShade).
	quadPass(mShadeFbo, mShade, [&](ofShader & s) {
		s.setUniformTexture("uMask", mMaskTex, 1); s.setUniformTexture("uAux", mAuxTex, 2); s.setUniformTexture("uLiq", mLiqTex, 3);
		s.setUniformTexture("uFib", fibNow.getTexture(), 4); s.setUniformTexture("uThreads", mThreads.getTexture(), 5);
		s.setUniform2f("uMaskSize", maskSize.x, maskSize.y); s.setUniform2f("uLiqSize", liqSize.x, liqSize.y);
		s.setUniform3f("uThreadCol", M_THREAD_COL.r, M_THREAD_COL.g, M_THREAD_COL.b);
		s.setUniform1f("uEdgeCool", M_EDGE_COOL); s.setUniform1f("uFromModel", MS::WARM_FROM_MODEL ? 1.0f : 0.0f);
		s.setUniform1f("uContrast", M_CONTRAST); s.setUniform1f("uGamma", M_GAMMA); s.setUniform1f("uBase", M_BASE);
		s.setUniform1f("uMature", M_MATURE); s.setUniform1f("uExposure", M_EXPOSURE); s.setUniform1f("uSheen", M_SHEEN);
		s.setUniform1f("uRelief", M_RELIEF); s.setUniform1f("uShine", M_SHINE); s.setUniform1f("uRim", M_RIM);
		s.setUniform1f("uSand", M_SAND); s.setUniform1f("uFibRelief", M_FIB_RELIEF); s.setUniform1f("uLightCol", M_LIGHT_COL);
		s.setUniform1f("uThreadBright", MS::THREADS_ON ? M_THREAD_BRIGHT : 0.0f);
		s.setUniform1f("uPulseGain", MS::THREADS_ON ? M_PULSE_GAIN : 0.0f);
		s.setUniform3f("uC0", M_C0.r, M_C0.g, M_C0.b); s.setUniform3f("uC1", M_C1.r, M_C1.g, M_C1.b);
		s.setUniform3f("uC2", M_C2.r, M_C2.g, M_C2.b); s.setUniform3f("uC3", M_C3.r, M_C3.g, M_C3.b);
		s.setUniform3f("uTrough", M_TROUGH.r, M_TROUGH.g, M_TROUGH.b);
	});
	// Bloom (page render): bright pass at 1/2, two blur levels (1/2 and 1/8).
	auto blur = [&](ofFbo & d, ofFbo & sF, float sx, float sy) {
		quadPass(d, mBlur, [&](ofShader & s) {
			s.setUniformTexture("uSrc", sF.getTexture(), 1);
			s.setUniform2f("uSrcSize", sF.getWidth(), sF.getHeight());
			s.setUniform2f("uStep", sx, sy);
		});
	};
	quadPass(mB1a, mBright, [&](ofShader & s) {
		s.setUniformTexture("uSrc", mShadeFbo.getTexture(), 1);
		s.setUniform2f("uSrcSize", mShadeFbo.getWidth(), mShadeFbo.getHeight());
		s.setUniform1f("uThresh", M_BLOOM_THRESH);
	});
	const float W2 = mFW / 2.0f, H2 = mFH / 2.0f, W8 = mFW / 8.0f, H8 = mFH / 8.0f;
	for (int i = 0; i < 2; i++) { blur(mB1b, mB1a, 2.0f / W2, 0.0f); blur(mB1a, mB1b, 0.0f, 2.0f / H2); }
	blur(mB2b, mB1a, 1.0f / W8, 0.0f); blur(mB2a, mB2b, 0.0f, 1.0f / H8);
	for (int i = 0; i < 2; i++) { blur(mB2b, mB2a, 2.0f / W8, 0.0f); blur(mB2a, mB2b, 0.0f, 2.0f / H8); }
	quadPass(mFinalFbo, mFinal, [&](ofShader & s) {
		s.setUniformTexture("uShade", mShadeFbo.getTexture(), 1); s.setUniformTexture("uBloomA", mB1a.getTexture(), 2);
		s.setUniformTexture("uBloomB", mB2a.getTexture(), 3);
		s.setUniform2f("uSizeA", mB1a.getWidth(), mB1a.getHeight()); s.setUniform2f("uSizeB", mB2a.getWidth(), mB2a.getHeight());
		s.setUniform1f("uBloom", M_BLOOM);
	});
	// Onto the sand through the calibration mesh.
	fbo.begin();
	ofClear(0, 0, 0, 255);
	ofPushStyle();
	ofEnableBlendMode(OF_BLENDMODE_DISABLED);
	ofSetColor(255);
	mPresent.begin();
	mPresent.setUniformTexture("uImage", mFinalFbo.getTexture(), 1);
	mPresent.setUniform1f("uScale", (float)std::max(1, MS::FIB_PX));
	mesh.draw();
	mPresent.end();
	ofPopStyle();
	ofEnableBlendMode(OF_BLENDMODE_ALPHA);
	fbo.end();
}

// GUI: the page's groups, labels, units, ranges and defaults (page GROUPS), plus the port's own settings.
void MycorrhizaRenderer::myceliumGui()
{
	MS & sim = field.getMycelium();
	ImGui::Text("Mycelium: %d growing threads, %d segments, %d edge cells", sim.activeThreads(), (int)sim.segments().size(), sim.edgeCount());
	ImGui::Text("Fusions %lld, stops on lit ground %lld", sim.fusions(), sim.patchStops());
	ImGui::Text("Step %.2f ms: touch %.2f, marks %.2f, mask %.2f, liquid %.2f, threads %.2f", field.getLastStepMs(), field.getPhaseMs(0),
		field.getPhaseMs(1), field.getPhaseMs(2), field.getPhaseMs(3), field.getPhaseMs(4));
	ImGui::Text("Upload %.2f ms, threads to GPU %.2f ms; projector px per image px %.2f", mUploadMs, mThreadMs, projPxPerFibPx());
	if (ImGui::CollapsingHeader("Touch")) {
		ImGui::SliderFloat("Liquid per touch (mm/s)", &MS::POUR, 0.0f, 6.0f);
		ImGui::Text("(liquid that moves the texture; the light itself appears wherever the sand is touched)");
		ImGui::Text("Simulated hand (the headless harness only; no effect on the sandbox):");
		ImGui::SliderFloat("Hand size (mm)", &M_BRUSH, 8.0f, 80.0f);
		ImGui::SliderFloat("Dig rate (mm/s)", &M_CARVE, 0.0f, 40.0f);
		ImGui::SliderFloat("Sand pushed ahead", &M_PILE, 0.0f, 1.5f);
	}
	if (ImGui::CollapsingHeader("Liquid motion (same model as the sandbox water)")) {
		ImGui::SliderFloat("Flow speed", &MS::PIPE_K, 2.0f, 120.0f);
		ImGui::SliderFloat("Thickness", &MS::VISC, 0.0f, 30.0f);
		ImGui::Text("(higher is slower and more like lava)");
		ImGui::SliderFloat("Stickiness (mm)", &MS::YIELD, 0.0f, 5.0f);
		ImGui::Text("(liquid stops flowing once nearly level)");
	}
	if (ImGui::CollapsingHeader("Texture in the light", ImGuiTreeNodeFlags_DefaultOpen)) {
		// As in the page, the five settings that shape the base pattern rebuild it when changed.
		bool rebuild = false;
		rebuild |= ImGui::SliderFloat("Streaks follow the stroke", &M_STROKE_W, 0.0f, 1.0f);
		ImGui::SliderFloat("Streak flow (px/s)", &M_STREAK_FLOW, 0.0f, 120.0f);
		rebuild |= ImGui::SliderFloat("Streak length (px)", &M_FIBRE_LEN, 6.0f, 140.0f);
		rebuild |= ImGui::SliderFloat("Fibre width (px)", &M_FIBRE, 0.6f, 6.0f);
		rebuild |= ImGui::SliderFloat("Swirl size", &M_SWIRL_SCALE, 1.0f, 20.0f);
		rebuild |= ImGui::SliderFloat("Streaks follow the slopes", &M_TEX_SLOPE, 0.0f, 1.0f);
		ImGui::SliderFloat("Carried by the liquid", &M_CARRY, 0.0f, 3.0f);
		ImGui::SliderFloat("Settling", &M_RELAX, 0.0f, 2.0f);
		if (rebuild) sim.requestBaseRebuild();
	}
	if (ImGui::CollapsingHeader("Memory and warming", ImGuiTreeNodeFlags_DefaultOpen)) {
		ImGui::SliderFloat("Trace memory (s)", &MS::TRACE_MEM, 10.0f, 1800.0f);
		ImGui::Text(MS::TRACE_MEM >= 1800.0f ? "(at the maximum the light and threads never fade)" : "(time to fade to about 10 %%)");
		ImGui::SliderFloat("Warm-up time (s)", &M_MATURE, 0.5f, 60.0f);
		ImGui::SliderFloat("Cool edges", &M_EDGE_COOL, 0.0f, 1.0f);
		ImGui::Checkbox("Warm from the model's recovery (instead of time)", &MS::WARM_FROM_MODEL);
		if (MS::WARM_FROM_MODEL)
			ImGui::SliderFloat("Model warming ease (s)", &MS::MODEL_EASE_SEC, 0.2f, 20.0f);
	}
	if (ImGui::CollapsingHeader("Light and colour", ImGuiTreeNodeFlags_DefaultOpen)) {
		ImGui::SliderFloat("Exposure", &M_EXPOSURE, 0.2f, 5.0f);
		ImGui::SliderFloat("Texture contrast", &M_CONTRAST, 1.0f, 10.0f);
		ImGui::SliderFloat("Darkness", &M_GAMMA, 0.4f, 4.0f);
		ImGui::SliderFloat("Base glow", &M_BASE, 0.0f, 1.0f);
		ImGui::SliderFloat("Colour from lighting", &M_LIGHT_COL, 0.0f, 1.0f);
		ImGui::SliderFloat("Sheen", &M_SHEEN, 0.0f, 3.0f);
		ImGui::SliderFloat("Sand relief", &M_RELIEF, 0.0f, 4.0f);
		ImGui::SliderFloat("Texture relief", &M_FIB_RELIEF, 0.0f, 10.0f);
		ImGui::SliderFloat("Sheen sharpness", &M_SHINE, 2.0f, 120.0f);
		ImGui::SliderFloat("Edge glow", &M_RIM, 0.0f, 2.0f);
		ImGui::SliderFloat("Bloom", &M_BLOOM, 0.0f, 3.0f);
		ImGui::SliderFloat("Bloom threshold", &M_BLOOM_THRESH, 0.0f, 1.5f);
		ImGui::SliderFloat("Sand visibility", &M_SAND, 0.0f, 0.5f);
		ImGui::Text("(room light on the unlit sand; 0 is a dark room)");
		if (ImGui::Button("Cyan and amber")) applyPalette(0);
		ImGui::SameLine();
		if (ImGui::Button("Blue and gold")) applyPalette(1);
		ImGui::SameLine();
		if (ImGui::Button("Violet")) applyPalette(2);
		ImGui::ColorEdit3("Fresh", &M_C0.r);
		ImGui::ColorEdit3("Next", &M_C1.r);
		ImGui::ColorEdit3("Warm", &M_C2.r);
		ImGui::ColorEdit3("Oldest", &M_C3.r);
		ImGui::ColorEdit3("Troughs", &M_TROUGH.r);
		ImGui::ColorEdit3("Threads", &M_THREAD_COL.r);
	}
	if (ImGui::CollapsingHeader("Threads", ImGuiTreeNodeFlags_DefaultOpen)) {
		ImGui::Checkbox("Threads on", &MS::THREADS_ON);
		ImGui::SliderFloat("Spawn rate (per s per 100 mm of edge)", &MS::SPAWN, 0.0f, 30.0f);
		ImGui::SliderFloat("Growth speed (mm/s)", &MS::SPEED, 2.0f, 60.0f);
		ImGui::SliderFloat("Curve amount (deg/cm)", &MS::CURVE, 0.0f, 120.0f);
		ImGui::SliderFloat("Curve smoothness (mm)", &MS::CORR, 3.0f, 80.0f);
		ImGui::SliderFloat("Branching (per 100 mm)", &MS::BRANCH, 0.0f, 20.0f);
		ImGui::SliderFloat("Tip lifetime (s)", &MS::TIP_LIFE, 1.0f, 60.0f);
		ImGui::SliderFloat("Follow the slopes", &MS::SLOPE, 0.0f, 1.0f);
		ImGui::SliderFloat("Width (px)", &MS::WIDTH, 0.4f, 4.0f);
		ImGui::SliderFloat("Minimum width on the projector (px)", &M_MIN_THREAD_PX, 0.5f, 4.0f);
		ImGui::SliderFloat("Thread brightness", &M_THREAD_BRIGHT, 0.0f, 3.0f);
		ImGui::SliderFloat("Pulse brightness", &M_PULSE_GAIN, 0.0f, 4.0f);
		ImGui::SliderFloat("Pulse speed", &M_PULSE_SPEED, 0.0f, 3.0f);
		ImGui::SliderFloat("Pulse spacing (px)", &M_PULSE_LEN, 5.0f, 200.0f);
		ImGui::SliderFloat("Pulse sharpness", &M_PULSE_SHARP, 1.0f, 12.0f);
		ImGui::SliderInt("Thread cap", &MS::MAX_THREADS, 50, 3000);
		ImGui::SliderFloat("Thread length kept (m)", &MS::THREAD_KEEP_M, 1.0f, 100.0f, "%.1f");
		ImGui::TextWrapped("Thread length kept: not a page slider. The page kept its last 60,000 segments (about 8 m) and overwrote the oldest; the same budget here.");
	}
}
